use std::{fs,path::Path};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/ready-solver246");let old="/home/ubuntu/src/zopro-perf-work/c7a-scale-profile245";let mut h=fs::read_to_string(Path::new(old).join("host.rs")).unwrap().replace(old,r.to_str().unwrap()).replace("78","90").replace("12696","8748").replace("64211","64301").replace("64133","64211");let a="let n=if pre{1}else if j[\"case\"][\"shape\"]==\"1x2\"{251}else{17};";assert_eq!(h.matches(a).count(),1);h=h.replace(a,"let n=if pre{1}else if phase==\"profile\"{251}else if j[\"case\"][\"shape\"]==\"1x2\"{151}else if j[\"case\"][\"shape\"]==\"2x2\"{51}else{17};");fs::write(r.join("host.rs"),h).unwrap();let a=fs::read_to_string(Path::new(old).join("analyze.rs")).unwrap();let end=a.find("assert_eq!(stats.len(),18)").unwrap();let mut prefix=a[..end].replace(old,r.to_str().unwrap()).replace("rows.len(),78","rows.len(),90").replace("events.len(),4","events.len(),2").replace("let z=row[\"arm\"]==\"ON\";","let z=true;");prefix.push_str(r#"
assert_eq!(stats.len(),6);assert_eq!(profiles.len(),6);let get=|arm:&str,panel:&str,b:u64|rows.iter().find(|v|v["phase"]=="profile"&&v["shape"]=="1x2"&&v["workers"]==96&&v["arm"]==arm&&v["panel"]==panel&&v["block"]==b).unwrap();let mut observers=vec![];for arm in["OFF","ON"]{for panel in["stat","dual"]{let v=(0..3).map(|b|get(arm,panel,b)["mean_ms"].as_f64().unwrap()/get(arm,"observer",b)["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let m=median(&v);observers.push(json!({"arm":arm,"panel":panel,"median_ratio":m,"blocks":v,"qualified":(1./1.05..=1.05).contains(&m)}));}}
let st=|arm:&str,b|stats.iter().find(|v|v["arm"]==arm&&v["block"]==b).unwrap();let mut comparisons=json!({});for event in["cycles:u","instructions:u"]{comparisons[event]=ratios((0..3).map(|b|st("ON",b)["PMU_per_proof"][event].as_f64().unwrap()/st("OFF",b)["PMU_per_proof"][event].as_f64().unwrap()).collect());}comparisons["CPI"]=ratios((0..3).map(|b|st("ON",b)["CPI"].as_f64().unwrap()/st("OFF",b)["CPI"].as_f64().unwrap()).collect());let passed=stats.iter().chain(profiles.iter()).chain(observers.iter()).all(|v|v["qualified"]==true);let result=json!({"quality_passed":passed,"comparisons_ON_over_OFF":comparisons,"observer_checks":observers,"PMU":stats,"profiles":profiles,"limitations":"Three-block primary96 diagnostics, not confidence estimates or32/96 scaling. Flat samples include inlining/skid; scheduler residence is not removable wall time or critical path. Absolute period coverage unvalidated.","canonical_count":64301});let p=r.join("analysis.json");assert!(!p.exists());fs::write(&p,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("quality_passed={passed}");println!("{}",serde_json::to_string_pretty(&result["comparisons_ON_over_OFF"]).unwrap());}
"#);fs::write(r.join("analyze.rs"),prefix).unwrap();println!("Posttransport host90 and primary96 profile readers prepared, no SDKcalls");}
